INSERT INTO public.questoes (id, material_id, enunciado, referencia, comentario_professor, ordem, publicado) VALUES
('1d4febfa-c670-4be4-82ad-84678181a98e', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, com a redação dada pela Emenda à Lei Orgânica nº 6/2023, o número de vereadores fixado para a Câmara Municipal de Palhoça é de:', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Auxiliar Legislativo / Questão: 21', 'O art. 36 da Lei Orgânica de Palhoça, com redação dada pela Emenda à Lei Orgânica nº 6/2023, fixa "em 21 (vinte e um) o número de vereadores na Câmara Municipal de Palhoça". As demais alternativas apresentam quantidades diversas da efetivamente fixada pela emenda municipal, que atualizou o número de cadeiras legislativas conforme os parâmetros constitucionais aplicáveis ao Município.', 1, true),
('78798911-6d60-4c8f-be29-58f905fcf720', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, compete privativamente à Câmara Municipal fixar o subsídio do Prefeito, do Vice-Prefeito, dos Vereadores, dos Secretários e do Procurador-Geral:', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Analista Legislativo / Questão: 47', 'O art. 40, V, da Lei Orgânica de Palhoça atribui à Câmara a competência privativa de "fixar o subsídio do Prefeito, do Vice-Prefeito, dos Vereadores, dos Secretários e Procurador-geral antes de findar a legislatura, nos termos da Constituição Federal". A exigência de fixação antes do término da legislatura busca evitar que os próprios legisladores beneficiários fixem sua remuneração para o período subsequente sem esse marco temporal de segurança. A alternativa "a" contraria a regra, pois a fixação deve ocorrer antes do fim da legislatura, e não a qualquer tempo. A alternativa "c" restringe indevidamente o prazo. A alternativa "d" inverte a competência, que é da Câmara, e não do Prefeito. A alternativa "e" não encontra previsão no dispositivo.', 2, true),
('798dc702-3596-4230-b652-1636ff42af49', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, é vedado ao Vereador, desde a expedição do diploma:', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Auxiliar Legislativo / Questão: 88', 'O art. 43, I, "a", da Lei Orgânica de Palhoça veda ao Vereador, "desde a expedição do diploma", "firmar ou manter contrato com pessoa jurídica de direito público municipal, autarquia, empresa pública, sociedade de economia mista, fundações ou empresas concessionários de serviço público, salvo quando o contrato obedecer às cláusulas uniformes". As demais alternativas ("a", "c", "d" e "e") descrevem vedações previstas no inciso II do mesmo artigo, cujo termo inicial é a posse, e não a simples diplomação, o que as torna incorretas para a pergunta formulada.', 3, true),
('4966380c-76ac-477a-a87d-67ce0bfcd215', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Segundo a Lei Orgânica de Palhoça, perderá o mandato o Vereador que deixar de comparecer, em cada sessão legislativa, a que fração das sessões ordinárias, salvo doença comprovada, licença ou missão autorizada?', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Analista Legislativo / Questão: 95', 'O art. 44, III, da Lei Orgânica de Palhoça prevê que perderá o mandato o Vereador "que deixar de comparecer, em cada sessão legislativa, à terça parte das sessões ordinárias, salvo doença comprovada, licença ou missão autorizada pela edilidade". As demais frações mencionadas nas alternativas não correspondem à efetivamente prevista no dispositivo, que estabelece o marco de um terço de faltas injustificadas como causa de perda de mandato.', 4, true),
('f7e9f983-5c8f-42e5-ba48-711f9c791055', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, a Lei Orgânica poderá ser emendada mediante proposta subscrita por, no mínimo, qual percentual dos eleitores votantes no Município?', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Analista Legislativo / Questão: 159', 'O art. 54, III, da Lei Orgânica de Palhoça prevê que a Lei Orgânica poderá ser emendada mediante proposta "de, pelo menos, cinco por cento (5%) dos eleitores votantes no Município". O mesmo percentual de 5% é exigido para a iniciativa popular de lei complementar ou ordinária, conforme o art. 55, § 1º. As demais alternativas trazem percentuais diversos, não correspondentes ao efetivamente exigido pelo dispositivo para a iniciativa popular de emenda.', 5, true),
('1fcae45f-71e1-41c4-b2e5-2da37149987c', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, o veto do Prefeito somente poderá ser rejeitado pela Câmara mediante o voto de:', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Analista Legislativo / Questão: 191', 'O art. 58, § 4º, da Lei Orgânica de Palhoça, com redação dada pela Emenda à Lei Orgânica nº 3/2013, dispõe que "o veto será apreciado pela Câmara dentro de trinta dias a contar do seu recebimento, só podendo ser rejeitado pelo voto da maioria absoluta dos Vereadores". As demais alternativas trazem quóruns diversos do efetivamente exigido (maioria simples, 2/3, 3/5 ou unanimidade), não correspondendo à regra vigente após a alteração promovida pela emenda municipal mencionada.', 6, true),
('f662dab8-a96f-451c-ba61-97a905146d5b', '75a1bad3-a204-4e47-9c91-235da54a89d6', 'Nos termos da Lei Orgânica de Palhoça, o controle externo da Câmara Municipal é exercido com o auxílio de qual órgão?', 'FUNDATEC 2026 / Prefeitura de Palhoça - SC / Analista Legislativo / Questão: 223', 'O art. 64, caput, da Lei Orgânica de Palhoça dispõe que "o controle externo da Câmara Municipal é exercido com o auxílio do Tribunal de Contas do Estado", elencando, em seguida, diversas atribuições desse órgão auxiliar, como emitir parecer prévio sobre as contas do Prefeito e julgar as contas dos administradores de recursos públicos. As demais instituições mencionadas nas alternativas — Ministério Público, Tribunal de Justiça, Controladoria-Geral e Assembleia Legislativa — não exercem essa função de auxílio direto ao controle externo camarário, conforme a estrutura de fiscalização prevista na Lei Orgânica municipal.', 7, true);
